public async Task<Fin<Unit>> Handle(UpdateProductCommand cmd, CancellationToken ct)
{
    var db = 
        from alternatives in GetEntities<Product>(p => cmd.AlternativeIds.Contains(p.Id))
        from _ in GetUpdateEntity<Product>(
            p => p.Id == cmd.ProductId,
            NotFoundError.New("Product not found"),
            opt => opt.AddInclude(p => p.Alternatives),
            product => product.Update(cmd.Dto, alternatives))
        select unit;

    return await db.RunSaveAsync(dbContext, EnvIO.New(null, ct));
}

private IO<Product> UploadProductImages(Product product, UpdateProductDto dto)
{
    return imageService.UploadProductImages(
        dto.Images, dto.IsMain, 
        product.Slug.Value, product.Category.ToString(), product.Brand.Name)
    .Map(results => product.AddImages([.. results]));
}

